    {
      "rank": 1,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "A decisive new class of quantum matter, with a robust theoretical principle and striking experimental realization.",
        "attribution": "Kane and Mele supplied the foundational quantum-spin-Hall theory; Molenkamp represents the key experimental realization.",
        "maturity": "The topological-insulator framework and its physical consequences have been extensively reproduced and developed.",
        "uncertainties": [
          "The full experimental attribution for the broader topological-insulator discovery is necessarily more distributed than three names."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B039",
      "proposed_laureates": [
        "Yoshinori Tokura",
        "Christian Pfleiderer",
        "Achim Rosch"
      ],
      "assessment": {
        "nobel_worthiness": "Magnetic skyrmions established a compelling topological magnetic state with emergent electrodynamics and substantial scientific reach.",
        "attribution": "Tokura and Pfleiderer anchor experimental discovery and characterization, while Rosch supplied influential theoretical understanding.",
        "maturity": "The phenomena are well established across materials and supported by quantitative theory and experiment.",
        "uncertainties": [
          "Priority and the appropriate balance between early theory, neutron-scattering evidence, and later materials work require careful reconstruction."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B042",
      "proposed_laureates": [
        "Antoine Georges",
        "Gabriel Kotliar",
        "Dieter Vollhardt"
      ],
      "assessment": {
        "nobel_worthiness": "Dynamical mean-field theory made strongly correlated electrons quantitatively tractable and transformed materials theory.",
        "attribution": "Kotliar and Georges are central to the modern formulation and applications; Vollhardt is essential to its conceptual development.",
        "maturity": "Its predictions, extensions, and combination with electronic-structure methods are deeply embedded in the field.",
        "uncertainties": [
          "The intellectual lineage includes several additional contributors, especially in early infinite-dimensional approaches."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B006",
      "proposed_laureates": [
        "Terunobu Miyazaki",
        "Jagadeesh S. Moodera",
        "Stuart S. P. Parkin"
      ],
      "assessment": {
        "nobel_worthiness": "Room-temperature tunnel magnetoresistance joined a clear quantum spin-transport effect to a technology of exceptional practical consequence.",
        "attribution": "Miyazaki and Moodera made seminal demonstrations, while Parkin was pivotal in advancing magnetic-device physics and application.",
        "maturity": "The effect is thoroughly confirmed, understood through spin-dependent tunnelling, and foundational to modern magnetic memory.",
        "uncertainties": [
          "The relative credit for discovery versus subsequent technological development needs precise historical assessment."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B024",
      "proposed_laureates": [
        "Michael V. Berry",
        "Yakir Aharonov"
      ],
      "assessment": {
        "nobel_worthiness": "Geometric quantum phase is a profound and durable physical insight with consequences from condensed matter to precision experiments.",
        "attribution": "Aharonov introduced the physically consequential gauge-potential effect, and Berry identified the general adiabatic geometric phase.",
        "maturity": "Both effects have extensive experimental support and provide indispensable modern physical language.",
        "uncertainties": [
          "Combining the Aharonov-Bohm and Berry effects into one citation may obscure distinct discoveries and wider relevant credit."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B041",
      "proposed_laureates": [
        "Eli Yablonovitch",
        "Sajeev John",
        "John D. Joannopoulos"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic band gaps created a powerful analogue of electronic band theory and a major platform for controlling light.",
        "attribution": "Yablonovitch and John were central originators of the concept, with Joannopoulos making foundational theoretical contributions.",
        "maturity": "The field has matured through many realizations and wide use in photonics.",
        "uncertainties": [
          "The extent to which the prize-worthy core is the original band-gap concept rather than broad photonic-crystal engineering requires delimitation."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B025",
      "proposed_laureates": [
        "Giacomo Ghiringhelli",
        "Lucio Braicovich",
        "Bernhard Keimer"
      ],
      "assessment": {
        "nobel_worthiness": "High-resolution resonant inelastic X-ray scattering has opened unusually direct access to collective excitations in quantum materials.",
        "attribution": "Braicovich and Ghiringhelli drove instrumental and methodological advances; Keimer represents transformative scientific application.",
        "maturity": "The technique is broadly adopted and has produced reproducible insight into correlated materials.",
        "uncertainties": [
          "This may be an exceptional instrument-and-method advance rather than a sufficiently singular discovery for a prize."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B050",
      "proposed_laureates": [
        "Hideo Hosono",
        "Xianhui Chen",
        "Zhongxian Zhao"
      ],
      "assessment": {
        "nobel_worthiness": "Iron-based superconductivity revealed a major new high-temperature-superconducting family and reshaped the study of correlated electrons.",
        "attribution": "Hosono led the initial breakthrough, while Chen and Zhao were central to early independent high-transition-temperature confirmations.",
        "maturity": "The materials family and its unconventional superconductivity are firmly established after extensive worldwide study.",
        "uncertainties": [
          "The microscopic pairing mechanism remains unsettled, and early experimental credit is distributed among several groups."
        ]
      }
    }
  ]
}
